/** List warehouse storage bins assigned to a SKU. */
export function binsForSku(sku) {
  return WAREHOUSE_BINS.filter((b) => b.sku === sku);
}

export function pickPath(skuList) {
  const bins = [];
  for (const sku of skuList || []) {
    const found = binsForSku(sku);
    if (found.length) bins.push(found[0]);
  }
  return bins.sort((a, b) => a.aisle - b.aisle || a.rack - b.rack || a.level - b.level);
}
